+/// binary across ordinary redraws before the release is interpreted.
+fn click(pty: &mut PtySession, x: u16, y: u16) {
+    pty.send(format!("\x1b[<0;{x};{y}M").as_bytes());
+    std::thread::sleep(Duration::from_millis(120));
+    pty.send(format!("\x1b[<0;{x};{y}m").as_bytes());
